package com.leetcode.backend.controller;
import com.leetcode.backend.model.*;import com.leetcode.backend.repository.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/lists") public class ProblemListController {final ProblemListRepository lists;final ProblemListItemRepository items;final UserRepository users;final ProblemRepository problems;ProblemListController(ProblemListRepository l,ProblemListItemRepository i,UserRepository u,ProblemRepository p){lists=l;items=i;users=u;problems=p;} User me(Authentication a){return users.findByUsername(a.getName()).orElseThrow();} ProblemList owned(Long id,Authentication a){return lists.findByIdAndUserId(id,me(a).getId()).orElseThrow(()->new org.springframework.security.access.AccessDeniedException("List not found."));}
@GetMapping public List<ProblemList> all(Authentication a){return lists.findByUserId(me(a).getId());}@PostMapping public ProblemList create(@RequestBody ProblemList b,Authentication a){b.setUser(me(a));return lists.save(b);}@PutMapping("/{id}") public ProblemList rename(@PathVariable Long id,@RequestBody ProblemList b,Authentication a){ProblemList l=owned(id,a);l.setName(b.getName());return lists.save(l);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id,Authentication a){lists.delete(owned(id,a));}@PostMapping("/{id}/problems/{problemId}") public ProblemList add(@PathVariable Long id,@PathVariable Long problemId,Authentication a){ProblemList l=owned(id,a);if(items.existsByListIdAndProblemId(id,problemId))throw new IllegalArgumentException("Problem is already in this list.");ProblemListItem i=new ProblemListItem();i.setList(l);i.setProblem(problems.findById(problemId).orElseThrow());i.setPosition(l.getItems().size());items.save(i);return owned(id,a);}@DeleteMapping("/{id}/problems/{problemId}") public void remove(@PathVariable Long id,@PathVariable Long problemId,Authentication a){ProblemList l=owned(id,a);l.getItems().removeIf(i->i.getProblem().getId().equals(problemId));lists.save(l);}}
